package auth_test

import (
	"net/http"
	"net/http/httptest"
	"net/url"
	"testing"

	"github.com/mbashem/cftracker/backend/internal/auth"
)

const testReturnOrigin = "https://frontend.example.test"

// Generated by Codex and not thoroughly checked for correctness.
func TestGitHubLoginUsesAllowedCallerOrigin(t *testing.T) {
	for _, testCase := range []struct {
		name, origin, referer, query, expectedOrigin string
		rejected                                     bool
	}{
		{name: "Origin supplies the frontend", origin: testReturnOrigin, expectedOrigin: testReturnOrigin},
		{name: "Referer supplies navigation origin", referer: testReturnOrigin + "/problems?q=1900", expectedOrigin: testReturnOrigin},
		{name: "second CORS origin is supported", origin: "http://localhost:5173", expectedOrigin: "http://localhost:5173"},
		{name: "Origin takes precedence over Referer", origin: testReturnOrigin, referer: "https://evil.test/", expectedOrigin: testReturnOrigin},
		{name: "requested alternate destination is ignored", origin: testReturnOrigin, query: "?return_to=https://evil.test/", expectedOrigin: testReturnOrigin},
		{name: "missing caller rejected", rejected: true},
		{name: "unlisted caller rejected", origin: "https://evil.test", referer: testReturnOrigin, rejected: true},
		{name: "lookalike caller rejected", origin: testReturnOrigin + ".evil.test", rejected: true},
		{name: "different port rejected", origin: testReturnOrigin + ":8443", rejected: true},
		{name: "null origin rejected", origin: "null", rejected: true},
		{name: "credentials in Referer rejected", referer: "https://user@frontend.example.test/", rejected: true},
		{name: "malformed Referer rejected", referer: "https://%", rejected: true},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			handler, provider := newAuthHandlerTestHandler(newMockAuthState(),
				auth.WithFrontendOrigins([]string{testReturnOrigin, "http://localhost:5173"}),
				auth.WithOAuthStateGenerator(func() (string, error) { return testGitHubOAuthState, nil }),
				auth.WithSessionTokenGenerator(func(string, int64) (string, error) { return "mock-session", nil }))
			request := httptest.NewRequest(http.MethodGet, testGitHubLoginPath+testCase.query, nil)
			request.Header.Set("Origin", testCase.origin)
			request.Header.Set("Referer", testCase.referer)
			response := httptest.NewRecorder()
			newAuthHandlerTestRouter(handler).ServeHTTP(response, request)
			if testCase.rejected {
				if response.Code != http.StatusBadRequest || len(provider.AuthorizationStates) != 0 || len(response.Result().Cookies()) != 0 {
					t.Fatalf("rejected login status=%d states=%v cookies=%v", response.Code, provider.AuthorizationStates, response.Result().Cookies())
				}
				return
			}
			if response.Code != http.StatusTemporaryRedirect || len(provider.AuthorizationRedirects) != 1 || provider.AuthorizationRedirects[0] != testCase.expectedOrigin+"/callback/auth-gh" {
				t.Fatalf("login status=%d redirects=%v", response.Code, provider.AuthorizationRedirects)
			}
			cookies := response.Result().Cookies()
			if len(cookies) != 1 || cookies[0].Name != githubOAuthStateCookieName {
				t.Fatalf("unexpected cookies=%v", cookies)
			}
			callback := httptest.NewRequest(http.MethodGet, testGitHubCallbackPath+"?"+url.Values{"state": {testGitHubOAuthState}, "code": {testGitHubOAuthCode}}.Encode(), nil)
			callback.Header.Set("Origin", testCase.expectedOrigin)
			callback.AddCookie(cookies[0])
			result := httptest.NewRecorder()
			newAuthHandlerTestRouter(handler).ServeHTTP(result, callback)
			if len(provider.AuthenticationRedirects) != 1 || provider.AuthenticationRedirects[0] != provider.AuthorizationRedirects[0] {
				t.Fatalf("exchange redirects=%v, login=%v", provider.AuthenticationRedirects, provider.AuthorizationRedirects)
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestGitHubCallbackRejectsUnlistedOriginBeforeProviderAccess(t *testing.T) {
	handler, provider := newAuthHandlerTestHandler(newMockAuthState())
	request := httptest.NewRequest(http.MethodGet, testGitHubCallbackPath+"?state="+testGitHubOAuthState, nil)
	request.Header.Set("Origin", "https://evil.test")
	request.AddCookie(&http.Cookie{Name: githubOAuthStateCookieName, Value: testGitHubOAuthState})
	response := httptest.NewRecorder()
	newAuthHandlerTestRouter(handler).ServeHTTP(response, request)
	if response.Code != http.StatusBadRequest || len(provider.AuthenticationCodes) != 0 {
		t.Fatalf("status=%d calls=%v", response.Code, provider.AuthenticationCodes)
	}
}
